const items = $input.all();

return items.map(item => {
  const r = item.json;
  const msg = $node['Telegram Trigger'].json.message;
  const chatId = msg.chat.id;
  const originalText = msg.text;
  const ts = new Date().toISOString();

  let parsed = null;
  let rawText = '';

  try {
    const parts = r.candidates?.[0]?.content?.parts || [];
    rawText = parts.map(p => p.text || '').join('').trim();

    if (!rawText) { throw new Error('No text in response'); }

    const firstBrace = rawText.indexOf('{');
    const lastBrace = rawText.lastIndexOf('}');

    if (firstBrace === -1 || lastBrace === -1 || lastBrace < firstBrace) {
      throw new Error('No JSON found');
    }

    let candidate = rawText.substring(firstBrace, lastBrace + 1);

    try {
      parsed = JSON.parse(candidate);
    } catch (e1) {
      let cleaned = candidate.replace(/,\s*([\]}])/g, '$1');
      try { parsed = JSON.parse(cleaned); }
      catch (e2) {
        let attempt = candidate.replace(/([\]}])/g, '');
        if (attempt.includes('"qualified"')) {
          let qMatch = attempt.match(/"qualified"\s*:\s*(true|false)/);
          let rMatch = attempt.match(/"reasoning"\s*:\s*"([^"]*)/);
          if (qMatch) { parsed = { qualified: qMatch[1] === 'true', reasoning: rMatch ? rMatch[1] : 'Sin razonamiento' }; }
        }
        if (!parsed) throw new Error('JSON parsing failed');
      }
    }
  } catch (e) {
    parsed = { qualified: false, reasoning: 'Error: ' + e.message.substring(0, 80) };
  }

  const qualified = parsed && parsed.qualified === true;
  const reasoning = (parsed && parsed.reasoning) ? parsed.reasoning : 'Sin razonamiento.';
  const h = qualified ? '[CALIFICADO]' : '[NO CALIFICADO]';

  return { json: { chatId, replyText: h + '\n\n' + reasoning, decision: h, reason: reasoning, originalText, timestamp: ts, _debug: rawText.substring(0, 200) } };
});
